$(document).ready(function(){$(".slickSlider").slick({slidesToShow:1,slidesToScroll:1,infinite:true,autoplay:true,autoplaySpeed:0,speed:5e3,cssEase:"linear",variableWidth:true,arrows:false,pauseOnHover:false,pauseOnFocus:false});$(".slider-container").each(function(){const $container=$(this);const $slider=$container.find(".slider_items");const $prevArrow=$container.find(".custom-prev");const $nextArrow=$container.find(".custom-next");$slider.slick({slidesToShow:2.3,slidesToScroll:1,infinite:false,arrows:true,prevArrow:$prevArrow,nextArrow:$nextArrow})})});